
/* =========================================
   LITEX — 3D WATER ENGINE
      Midnight Futurism
      ========================================= */

      import * as THREE from
        "https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js";

        const canvas = document.getElementById("water-canvas");

        if (!canvas) {
          console.warn("Litex water canvas not found.");
          } else {

            /* 1. SCENE SETUP */

              let renderer;

                try {
                    renderer = new THREE.WebGLRenderer({
                          canvas,
                                alpha: true,
                                      antialias: false,
                                            powerPreference: "low-power"
                                                });
                                                  } catch (error) {
                                                      console.warn("WebGL is unavailable.", error);
                                                        }

                                                          if (renderer) {

                                                              const scene = new THREE.Scene();

                                                                  const camera = new THREE.PerspectiveCamera(
                                                                        48,
                                                                              window.innerWidth / window.innerHeight,
                                                                                    0.1,
                                                                                          100
                                                                                              );

                                                                                                  camera.position.set(0, 7, 9);
                                                                                                      camera.lookAt(0, 0, 0);

                                                                                                          /* 2. RENDERING QUALITY */

                                                                                                              const isMobile = window.innerWidth < 768;

                                                                                                                  renderer.setPixelRatio(
                                                                                                                        Math.min(window.devicePixelRatio || 1, isMobile ? 1 : 1.5)
                                                                                                                            );

                                                                                                                                renderer.setSize(
                                                                                                                                      window.innerWidth,
                                                                                                                                            window.innerHeight
                                                                                                                                                );

                                                                                                                                                    renderer.setClearColor(0x000000, 0);

                                                                                                                                                        /* 3. WATER SHADERS */

                                                                                                                                                            const vertexShader = `

                                                                                                                                                                  uniform float uTime;

                                                                                                                                                                        varying vec2 vUv;
                                                                                                                                                                              varying float vWave;

                                                                                                                                                                                    void main() {

                                                                                                                                                                                            vUv = uv;

                                                                                                                                                                                                    vec3 pos = position;

                                                                                                                                                                                                            float wave1 = sin(
                                                                                                                                                                                                                      pos.x * 0.45 + uTime * 0.5
                                                                                                                                                                                                                              ) * 0.18;

                                                                                                                                                                                                                                      float wave2 = sin(
                                                                                                                                                                                                                                                pos.y * 0.65 - uTime * 0.35
                                                                                                                                                                                                                                                        ) * 0.12;

                                                                                                                                                                                                                                                                float wave3 = sin(
                                                                                                                                                                                                                                                                          (pos.x + pos.y) * 0.22 + uTime * 0.25
                                                                                                                                                                                                                                                                                  ) * 0.10;

                                                                                                                                                                                                                                                                                          float wave = wave1 + wave2 + wave3;

                                                                                                                                                                                                                                                                                                  pos.z += wave;

                                                                                                                                                                                                                                                                                                          vWave = wave;

                                                                                                                                                                                                                                                                                                                  gl_Position =
                                                                                                                                                                                                                                                                                                                            projectionMatrix *
                                                                                                                                                                                                                                                                                                                                      modelViewMatrix *
                                                                                                                                                                                                                                                                                                                                                vec4(pos, 1.0);

                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                          `;

                                                                                                                                                                                                                                                                                                                                                              const fragmentShader = `

                                                                                                                                                                                                                                                                                                                                                                    uniform float uTime;
                                                                                                                                                                                                                                                                                                                                                                          uniform vec4 uRipples[6];

                                                                                                                                                                                                                                                                                                                                                                                varying vec2 vUv;
                                                                                                                                                                                                                                                                                                                                                                                      varying float vWave;

                                                                                                                                                                                                                                                                                                                                                                                            void main() {

                                                                                                                                                                                                                                                                                                                                                                                                    vec3 deepBlue = vec3(0.008, 0.025, 0.075);
                                                                                                                                                                                                                                                                                                                                                                                                            vec3 oceanBlue = vec3(0.015, 0.09, 0.19);
                                                                                                                                                                                                                                                                                                                                                                                                                    vec3 silverBlue = vec3(0.20, 0.48, 0.62);

                                                                                                                                                                                                                                                                                                                                                                                                                            float depth = smoothstep(
                                                                                                                                                                                                                                                                                                                                                                                                                                      0.0, 1.0, vUv.y
                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                      vec3 waterColor = mix(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                deepBlue,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          oceanBlue,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    depth
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    float reflections =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              sin(vUv.x * 35.0 + uTime * 0.35) *
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        sin(vUv.y * 24.0 - uTime * 0.25);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                float highlights = smoothstep(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          0.72, 0.98, reflections
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          waterColor += silverBlue * highlights * 0.16;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  waterColor +=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            silverBlue * abs(vWave) * 0.18;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    /* TOUCH RIPPLE EFFECTS */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            float rippleLight = 0.0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for (int i = 0; i < 6; i++) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              vec4 ripple = uRipples[i];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        float age = uTime - ripple.z;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (age >= 0.0 && age < 3.0) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              float distanceFromRipple =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            distance(vUv, ripple.xy);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        float ring = abs(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      distanceFromRipple - age * 0.16
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              float fade = 1.0 - age / 3.0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          rippleLight +=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        exp(-ring * 110.0) *
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      fade *
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ripple.w;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              waterColor +=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        silverBlue * rippleLight * 0.55;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                gl_FragColor = vec4(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          waterColor,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    0.88
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          /* 4. WATER MATERIAL */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const rippleSlots = Array.from(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    { length: 6 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          () => new THREE.Vector4(-2, -2, -10, 0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const waterMaterial = new THREE.ShaderMaterial({

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        transparent: true,

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              uniforms: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      uTime: { value: 0 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              uRipples: { value: rippleSlots }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          vertexShader,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                fragmentShader

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        /* 5. WATER SURFACE */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const waterGeometry = new THREE.PlaneGeometry(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  45,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        45,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              isMobile ? 90 : 140,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    isMobile ? 90 : 140
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const water = new THREE.Mesh(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  waterGeometry,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        waterMaterial
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                water.rotation.x = -Math.PI / 2;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    scene.add(water);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        /* 6. RIPPLE INTERACTION */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let rippleIndex = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function createRipple(event) {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const target = event.target;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    target instanceof Element &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            target.closest(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "a, button, input, textarea, select, [role='dialog']"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const x = event.clientX / window.innerWidth;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const y = 1 - event.clientY / window.innerHeight;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    rippleSlots[rippleIndex].set(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            x,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    y,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            waterMaterial.uniforms.uTime.value,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                rippleIndex = (rippleIndex + 1) % 6;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        window.addEventListener(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "pointerdown",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    createRipple,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          { passive: true }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  /* 7. RESPONSIVE RESIZING */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function resizeWater() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const width = window.innerWidth;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const height = window.innerHeight;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        camera.aspect = width / height;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              camera.updateProjectionMatrix();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    renderer.setPixelRatio(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Math.min(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      window.devicePixelRatio || 1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                width < 768 ? 1 : 1.5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    renderer.setSize(width, height);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            window.addEventListener(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "resize",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        resizeWater
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                /* 8. ANIMATION */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const reducedMotion = window.matchMedia(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "(prefers-reduced-motion: reduce)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ).matches;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const clock = new THREE.Clock();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function animate() {

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const elapsed = clock.getElapsedTime();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  waterMaterial.uniforms.uTime.value = elapsed;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        renderer.render(scene, camera);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (!reducedMotion) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      requestAnimationFrame(animate);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    animate();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
